// CatalogServiceServer is the server API for CatalogService service.
// All implementations must embed UnimplementedCatalogServiceServer
// for forward compatibility.
//
// CatalogService owns the registry of two domain entities:
//
//   - Territory — a parent scene (terrain, photogrammetry mesh) the
//     viewer walks around in.
//   - Model     — a placeable asset (equipment, fixture) overlaid on a
//     territory at a specific transform.
//
// Each entity has its own artifact family (territory_artifacts /
// model_artifacts) holding the converted GLB outputs per LOD. Source
// files are stored as content-addressed ZIP archives in BlobStore;
// the catalog only keeps the hash.
type CatalogServiceServer interface {
	ListTerritories(context.Context, *ListTerritoriesRequest) (*ListTerritoriesResponse, error)
	// ResolveTerritorySlugs labels territory ids for the audit journal, which
	// knows a placement's parent only as the number in its row snapshot. The
	// public Territory message carries a slug and no id on purpose; adding one
	// would change a shape the whole scene reads for an internal lookup.
	ResolveTerritorySlugs(context.Context, *ResolveTerritorySlugsRequest) (*ResolveTerritorySlugsResponse, error)
	// ResolveLabels names catalog rows for the audit journal, whose snapshots
	// carry a parent or a target only as a number. It is the plural, multi-kind
	// sibling of ResolveTerritorySlugs, which stays because the entry-level
	// enrichment already calls it.
	ResolveLabels(context.Context, *ResolveLabelsRequest) (*ResolveLabelsResponse, error)
	// ResolveBlobAccess answers whether a caller scoped to scope_admin_id may read
	// the bytes behind a content-addressed hash. A blob is reachable when it
	// belongs to a model (models are a shared library) or to a territory assigned
	// to that caller. An empty scope_admin_id means Root and disables the filter.
	ResolveBlobAccess(context.Context, *ResolveBlobAccessRequest) (*ResolveBlobAccessResponse, error)
	GetTerritory(context.Context, *GetTerritoryRequest) (*GetTerritoryResponse, error)
	UpsertTerritory(context.Context, *UpsertTerritoryRequest) (*UpsertTerritoryResponse, error)
	UpdateTerritory(context.Context, *UpdateTerritoryRequest) (*UpdateTerritoryResponse, error)
	DeleteTerritory(context.Context, *DeleteTerritoryRequest) (*DeleteTerritoryResponse, error)
	RegisterTerritoryArtifact(context.Context, *RegisterTerritoryArtifactRequest) (*RegisterTerritoryArtifactResponse, error)
	ListTerritoryArtifacts(context.Context, *ListTerritoryArtifactsRequest) (*ListTerritoryArtifactsResponse, error)
	GetTerritoryArtifact(context.Context, *GetTerritoryArtifactRequest) (*GetTerritoryArtifactResponse, error)
	DeleteTerritoryArtifacts(context.Context, *DeleteTerritoryArtifactsRequest) (*DeleteTerritoryArtifactsResponse, error)
	SetTerritoryRescaleBaseline(context.Context, *SetTerritoryRescaleBaselineRequest) (*SetTerritoryRescaleBaselineResponse, error)
	RescaleTerritoryPlacements(context.Context, *RescaleTerritoryPlacementsRequest) (*RescaleTerritoryPlacementsResponse, error)
	SetTerritoryAdmins(context.Context, *SetTerritoryAdminsRequest) (*SetTerritoryAdminsResponse, error)
	GetTerritoryAdmins(context.Context, *GetTerritoryAdminsRequest) (*GetTerritoryAdminsResponse, error)
	// ListTerritoryAdmins is GetTerritoryAdmins for many territories in one
	// query: the access screen used to ask once per territory.
	ListTerritoryAdmins(context.Context, *ListTerritoryAdminsRequest) (*ListTerritoryAdminsResponse, error)
	ListModels(context.Context, *ListModelsRequest) (*ListModelsResponse, error)
	GetModel(context.Context, *GetModelRequest) (*GetModelResponse, error)
	UpsertModel(context.Context, *UpsertModelRequest) (*UpsertModelResponse, error)
	UpdateModel(context.Context, *UpdateModelRequest) (*UpdateModelResponse, error)
	DeleteModel(context.Context, *DeleteModelRequest) (*DeleteModelResponse, error)
	RegisterModelArtifact(context.Context, *RegisterModelArtifactRequest) (*RegisterModelArtifactResponse, error)
	ListModelArtifacts(context.Context, *ListModelArtifactsRequest) (*ListModelArtifactsResponse, error)
	GetModelArtifact(context.Context, *GetModelArtifactRequest) (*GetModelArtifactResponse, error)
	ListPlacements(context.Context, *ListPlacementsRequest) (*ListPlacementsResponse, error)
	CreatePlacement(context.Context, *CreatePlacementRequest) (*CreatePlacementResponse, error)
	// CreatePlacements lands 1–100 placements on one territory in one
	// transaction: all of them, or none.
	CreatePlacements(context.Context, *CreatePlacementsRequest) (*CreatePlacementsResponse, error)
	UpdatePlacement(context.Context, *UpdatePlacementRequest) (*UpdatePlacementResponse, error)
	SetPlacementVisibility(context.Context, *SetPlacementVisibilityRequest) (*SetPlacementVisibilityResponse, error)
	DeletePlacement(context.Context, *DeletePlacementRequest) (*DeletePlacementResponse, error)
	// Measurements are scoped by territory_slug on every call: an id that
	// belongs to another territory is NOT_FOUND, same as an unknown one.
	ListMeasurements(context.Context, *ListMeasurementsRequest) (*ListMeasurementsResponse, error)
	CreateMeasurement(context.Context, *CreateMeasurementRequest) (*CreateMeasurementResponse, error)
	UpdateMeasurement(context.Context, *UpdateMeasurementRequest) (*UpdateMeasurementResponse, error)
	DeleteMeasurement(context.Context, *DeleteMeasurementRequest) (*DeleteMeasurementResponse, error)
	DeleteMeasurements(context.Context, *DeleteMeasurementsRequest) (*DeleteMeasurementsResponse, error)
	// Bulk placement writes: one UPDATE over ids on territory_slug in one
	// transaction. Every id must be on the territory or nothing changes and the
	// answer is NOT_FOUND; a repeated id counts once; 1–1000 ids.
	SetPlacementsHidden(context.Context, *SetPlacementsHiddenRequest) (*SetPlacementsHiddenResponse, error)
	SetPlacementsGroup(context.Context, *SetPlacementsGroupRequest) (*SetPlacementsGroupResponse, error)
	// Placement groups are scoped by territory_slug like measurements: an id of
	// another territory is NOT_FOUND, same as an unknown one.
	ListPlacementGroups(context.Context, *ListPlacementGroupsRequest) (*ListPlacementGroupsResponse, error)
	CreatePlacementGroup(context.Context, *CreatePlacementGroupRequest) (*CreatePlacementGroupResponse, error)
	RenamePlacementGroup(context.Context, *RenamePlacementGroupRequest) (*RenamePlacementGroupResponse, error)
	DeletePlacementGroup(context.Context, *DeletePlacementGroupRequest) (*DeletePlacementGroupResponse, error)
	mustEmbedUnimplementedCatalogServiceServer()
}

